await (async()=>{const S='2026-01-01',K=/졸업|학위수여|수료생|종합시험|콜로키움|학위청구|졸업작품|졸업전시|졸업연주|졸업공연|졸업논문|졸업인증|졸업심사/,X=/취업|채용|인턴|구인|자료|갤러리|사진|FAQ|Q&A|일정|교원자격|동문/;const L=[...document.querySelectorAll('a')].map(a=>[a.textContent.replace(/\s+/g,' ').trim(),a.getAttribute('href')||'']).filter(([t,h])=>/공지|학사|공고|NOTICE|Notice|소식/.test(t)&&!X.test(t)&&h.startsWith('/')&&/\.do/.test(h)&&t.length<20);const B=[...new Map(L.map(([t,h])=>[h.split('?')[0],t])).entries()];const o=[`#site ${location.host}|${document.title.replace(/\s*\|.*$/,'')}`],R=new Map();const P=s=>new DOMParser().parseFromString(s,'text/html');for(const[p,nm]of B.slice(0,6)){let n=0,old='',e='none';if(/subview\.do/.test(p)){const h=await fetch(p).then(r=>r.text()).catch(()=>'');const b=(h.match(/\/bbs\/[^\/"']+\/\d+\/artclList\.do/)||[''])[0];if(!b){o.push(`#board ${nm}|${p}|k2web-nolist|0|`);continue}const x=await fetch(b.replace('artclList.do','rssList.do?row=200')).then(r=>r.text());const d=new DOMParser().parseFromString(x,'text/xml');const it=[...d.querySelectorAll('item')];old='9999';for(const i of it){const t=i.querySelector('title')?.textContent.replace(/\s+/g,' ').trim()||'';const l=i.querySelector('link')?.textContent||'';const no=(l.match(/\/(\d+)\/artclView/)||[])[1]||l;const pd=new Date(i.querySelector('pubDate')?.textContent||'');const dt=isNaN(pd)?'':pd.toISOString().slice(0,10);if(dt&&dt<old)old=dt;if(dt>=S&&K.test(t)&&!R.has(no))R.set(no,`${no}|${dt}||${nm}|${t.slice(0,70)}`)}o.push(`#board ${nm}|${b}|k2web-rss|${it.length}|${old}`);continue}for(let f=0;f<200;f+=50){const h=await fetch(`${p}?mode=list&articleLimit=50&article.offset=${f}`).then(r=>r.text()).catch(()=>'');const T=[...P(h).querySelectorAll('table tbody tr')].filter(t=>t.querySelector('a[href*="articleNo="]'));if(!T.length)break;e='sm_cms';let po='9999';for(const t of T){const a=t.querySelector('a[href*="articleNo="]'),no=a.getAttribute('href').match(/articleNo=(\d+)/)[1],td=[...t.querySelectorAll('td')].map(x=>x.textContent.replace(/\s+/g,' ').trim()),dt=(t.textContent.match(/\d{4}[.-]\d{2}[.-]\d{2}/)||[''])[0].replace(/\./g,'-'),hi=td.filter(x=>/^\d+$/.test(x)).pop()||'',pin=/^공지/.test(td[0]||''),ti=a.textContent.replace(/\s+/g,' ').trim();n++;if(!pin&&dt&&dt<po)po=dt;if(dt>=S&&K.test(ti)&&!R.has(no))R.set(no,`${no}|${dt}|${hi}|${nm}|${ti.slice(0,70)}`)}old=po;if(po<S)break}o.push(`#board ${nm}|${p}|${e}|${n}|${old}`)}return o.concat([...R.values()]).join('\n')})()
